mapper.select:
SELECT *
FROM PRODUCT
WHERE prod_code = #{prod_code}

SELECT ISNULL(E.jisi_h_su,0) AS jisi_h_su, ROUND(ISNULL(E.jisi_h_jung,0),2) AS jisi_h_jung, ISNULL(E.jisi_h_code,0) AS jisi_h_code, CONVERT(VARCHAR(10),A.ord_input,23) AS ord_input, A.ord_code, A.ord_su, A.ord_danj, B.prod_no, B.prod_name, C.corp_name, B.PROD_PG + '' + B.PROD_PG1 + '~' + B.PROD_PG2 AS jisi_h_work_q_hard_std, B.PROD_GD1 + ' ' + B.PROD_GD3 + ' '+ B.PROD_GD2 +'기준 '+ B.PROD_GD4 + '~' + B.PROD_GD5 AS jisi_h_work_q_hard_std2, D.wstd_gj11 AS jisi_h_pre_temp, D.wstd_gj12 AS jisi_h_chim_temp, D.wstd_gj13 AS jisi_h_diff_temp, D.wstd_gj14 AS jisi_h_gang_temp, D.wstd_gj15 AS jisi_h_crack_temp, D.wstd_gj16 AS jisi_h_cold_temp, D.wstd_gj21 AS jisi_h_pre_time, D.wstd_gj22 AS jisi_h_chim_time, D.wstd_gj23 AS jisi_h_diff_time, D.wstd_gj24 AS jisi_h_gang_time, D.wstd_gj25 AS jisi_h_crack_time, D.wstd_gj26 AS jisi_h_cold_time, D.wstd_gj31 AS jisi_h_pre_cp, D.wstd_gj32 AS jisi_h_chim_cp, D.wstd_gj33 AS jisi_h_diff_cp, D.wstd_gj34 AS jisi_h_gang_cp, D.wstd_gj35 AS jisi_h_crack_cp, CASE WHEN D.wstd_gj42 IS NOT NULL THEN D.wstd_gj42 WHEN D.wstd_gj43 IS NOT NULL THEN D.wstd_gj43 WHEN D.wstd_gj44 IS NOT NULL THEN D.wstd_gj44 END AS jisi_h_rx, CASE WHEN D.wstd_gj52 IS NOT NULL THEN D.wstd_gj52 WHEN D.wstd_gj53 IS NOT NULL THEN D.wstd_gj53 WHEN D.wstd_gj54 IS NOT NULL THEN D.wstd_gj54 END AS jisi_h_lpg, D.wstd_gj17 AS jisi_h_agi, D.wstd_ready AS jisi_t_temp, D.wstd_worktime AS jisi_t_time, D.WSTD_T32, D.WSTD_T33, D.WSTD_T41, D.WSTD_T42, D.WSTD_T87, D.WSTD_T43, D.WSTD_T44, D.WSTD_T51, D.WSTD_T52, D.WSTD_T53, D.WSTD_T54, D.WSTD_T30, 0 AS jisi_default_su FROM ORDERT A LEFT OUTER JOIN PRODUCT B ON A.PROD_CODE = B.PROD_CODE LEFT OUTER JOIN CORP C ON B.CORP_CODE = C.CORP_CODE LEFT OUTER JOIN ( SELECT *, ROW_NUMBER() OVER(PARTITION BY prod_code ORDER BY prod_code) AS rnum FROM workstd ) D ON B.PROD_CODE = D.PROD_CODE LEFT OUTER JOIN ( SELECT jisi_ord_code, SUM(jisi_h_su) AS jisi_h_su, ROUND(SUM(jisi_h_jung),2) AS jisi_h_jung, MAX(jisi_h_code) AS jisi_h_code FROM tb_workheat GROUP BY jisi_ord_code ) E ON A.ord_code = E.jisi_ord_code WHERE ord_code IN
#{ord_code}
AND D.rnum = 1


SELECT CONCAT(CONVERT(VARCHAR(6),GETDATE(),12),#{jisi_h_hogi},
(
	(				
		SELECT COUNT(h_count)+1
		FROM (
			SELECT jisi_lot, COUNT(*) AS h_count
			FROM tb_workheat
			WHERE 1=1
			AND jisi_h_hogi = #{jisi_h_hogi}
			AND CONVERT(VARCHAR(6),CAST(jisi_h_regtime AS DATE),12) = CONVERT(VARCHAR(6),GETDATE(),12)
			GROUP BY jisi_lot
		) AS A				
	)
),
 	(SELECT COUNT(ccc)-1
	FROM (
		SELECT prod_code, COUNT(*) AS ccc
		FROM ordert
		WHERE ord_code IN 
		
			#{ord_code}
		
		GROUP BY prod_code
	) AS B)
) AS jisi_lot

SELECT * FROM ( SELECT CONVERT(VARCHAR(20),A.ord_input,23) AS ord_input, A.ord_code, D.corp_name, C.prod_name, C.prod_no, C.prod_code, A.ord_su, ISNULL(B.jisi_h_su,0) AS jisi_h_su, (A.ord_su - ISNULL(B.jisi_h_su,0)) AS jisi_diff_su, ISNULL(REPLACE(E.wstd_t43,',',''),0) AS jisi_j_su, rnum FROM ordert A LEFT OUTER JOIN ( SELECT ord_code, SUM(ilbo_su) AS jisi_h_su FROM workilbo WHERE ilbo_gubn = 'J' GROUP BY ord_code ) B ON A.ord_code = B.ord_code LEFT OUTER JOIN PRODUCT C ON A.prod_code = C.prod_code LEFT OUTER JOIN CORP D ON D.CORP_CODE = C.CORP_CODE LEFT OUTER JOIN ( SELECT *, ROW_NUMBER() OVER(PARTITION BY prod_code ORDER BY prod_code) AS rnum FROM workstd ) E ON C.PROD_CODE = E.PROD_CODE ) AS AA WHERE 1=1 AND ord_input >= CONCAT(#{sdate},' 00:00:00') AND ord_input <= CONCAT(#{edate},' 23:59:59') AND prod_code = #{prod_code} AND jisi_diff_su > 0 AND ord_code < #{ord_code} AND ord_code NOT IN
#{ord_codes}
AND rnum = 1 ORDER BY ord_code

mapper.insert:
INSERT INTO tb_workheat ( jisi_h_code, jisi_lot, jisi_j_code_ref, jisi_h_hogi, jisi_h_user_code, jisi_h_regtime, jisi_h_su, jisi_h_jung, jisi_h_pre_temp, jisi_h_chim_temp, jisi_h_diff_temp, jisi_h_gang_temp, jisi_h_crack_temp, jisi_h_cold_temp, jisi_t_temp, jisi_h_pre_time, jisi_h_chim_time, jisi_h_diff_time, jisi_h_gang_time, jisi_h_crack_time, jisi_h_cold_time, jisi_t_time, jisi_h_chim_cp, jisi_h_diff_cp, jisi_h_gang_cp, jisi_h_pre_h2, jisi_h_chim_h2, jisi_h_diff_h2, jisi_h_gang_h2, jisi_h_pre_nh3, jisi_h_chim_nh3, jisi_h_diff_nh3, jisi_h_gang_nh3, jisi_h_rx, jisi_h_lpg, jisi_h_agi, jisi_t_hogi, jisi_ord_code, jisi_lot_view ) VALUES ( (SELECT ISNULL(MAX(jisi_h_code), 0)+1 FROM tb_workheat), #{jisi_lot}, #{jisi_j_code_ref}, #{jisi_h_hogi}, #{jisi_user_code}, CONVERT(VARCHAR(20),GETDATE(),20), #{jisi_h_su}, #{jisi_h_jung}, #{jisi_h_pre_temp}, #{jisi_h_chim_temp}, #{jisi_h_diff_temp}, #{jisi_h_gang_temp}, #{jisi_h_crack_temp}, #{jisi_h_cold_temp}, #{jisi_t_temp}, #{jisi_h_pre_time}, #{jisi_h_chim_time}, #{jisi_h_diff_time}, #{jisi_h_gang_time}, #{jisi_h_crack_time}, #{jisi_h_cold_time}, #{jisi_t_time}, #{jisi_h_chim_cp}, #{jisi_h_diff_cp}, #{jisi_h_gang_cp}, #{jisi_h_pre_h2}, #{jisi_h_chim_h2}, #{jisi_h_diff_h2}, #{jisi_h_gang_h2}, #{jisi_h_pre_nh3}, #{jisi_h_chim_nh3}, #{jisi_h_diff_nh3}, #{jisi_h_gang_nh3}, #{jisi_h_rx}, #{jisi_h_lpg}, #{jisi_h_agi}, #{jisi_t_hogi}, #{jisi_ord_code}, #{ilbo_lot} );
INSERT INTO WORKILBO (ilbo_code, ilbo_no, ord_code, ilbo_gubn, ilbo_lot, ilbo_su, ilbo_jung, user_code, ilbo_g11, ilbo_g13, ilbo_g23, ilbo_g24, ilbo_g25, ilbo_g26, ilbo_g27, ilbo_g31, ilbo_g32, ilbo_g33, ilbo_g34, ilbo_g35, ilbo_pg6, ilbo_pc, ilbo_pn, ilbo_g42, ilbo_g43, ilbo_strt, fac_code) VALUES (#{ilbo_code}, #{ilbo_no}, #{ord_code}, #{ilbo_gubn}, #{ilbo_lot}, #{ilbo_su}, #{ilbo_jung}, #{user_code}, #{jisi_h_rx}, #{jisi_h_cold_time}, #{jisi_h_chim_temp}, #{jisi_h_chim_time}, #{jisi_h_chim_cp}, #{jisi_h_diff_time}, #{jisi_h_diff_cp}, #{jisi_h_gang_temp}, #{jisi_h_gang_time}, #{jisi_h_gang_cp}, #{jisi_h_cold_temp}, #{jisi_h_agi}, #{jisi_h_diff_temp}, #{ilbo_pc}, #{ilbo_pn}, #{jisi_h_pre_time}, #{jisi_h_pre_temp} , CONVERT(VARCHAR(20),GETDATE(),20), #{fac_code} );
INSERT INTO tb_worktracking (tracking_regdate, tracking_lot, tracking_ord_code, tracking_ilbo_lot) VALUES (CONVERT(VARCHAR(23),GETDATE(),21),#{jisi_lot},#{ord_code},#{ilbo_lot});

